#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<long long> T(N), F(M);
    for (auto &x : T) cin >> x;
    for (auto &x : F) cin >> x;

    sort(T.rbegin(), T.rend());

    priority_queue<pair<long long, int>,
                   vector<pair<long long, int>>,
                   greater<pair<long long, int>>> pq;

    for (int j = 0; j < M; ++j) {
        pq.push({0, j});
    }

    long long answer = 0;
    for (int i = 0; i < N; ++i) {
        auto [coefficient, j] = pq.top();
        pq.pop();

        answer += T[i] * coefficient;
        pq.push({coefficient + F[j], j});
    }

    cout << answer << '\n';
    return 0;
}
